mapper.select:
select
, mfm.name as fee_model_name, u.status, u.user_name as account_name, p.business_name as parent_business_name
from shop mt left join merchant_fee_model mfm on mt.merchant_fee_model_id = mfm.id
    left join sys_user u on mt.user_id = u.user_id
    left join shop p on mt.parent_id = p.id

     and u.status = #{status}

     and mt.id = #{id}
     and mt.user_id = #{userId}
     and mt.business_name like concat('%', #{businessName}, '%')
     and mt.business_no = #{businessNo}
     and mt.business_address = #{businessAddress}
     and mt.country = #{country}
     and mt.industry = #{industry}
     and mt.side_industry = #{sideIndustry}
     and mt.registration_date = #{registrationDate}
     and mt.registration_address = #{registrationAddress}
     and mt.shareholding_structure = #{shareholdingStructure}
     and mt.turnover_year = #{turnoverYear}
     and mt.turnover_week = #{turnoverWeek}
     and mt.station = #{station}
     and mt.website = #{website}
     and mt.supplier_name like concat('%', #{supplierName}, '%')
     and mt.supplier_contracts = #{supplierContracts}
     and mt.business_profile_status = #{businessProfileStatus}
     and mt.director_profile_status = #{directorProfileStatus}
     and mt.director_document_status = #{directorDocumentStatus}
     and mt.saas_user_corporation_id = #{saasUserCorporationId}

        and date_format(convert_tz(mt.created_at,'+00:00','+08:00'),'%Y-%m-%d') = date_format(#{createdAt},'%Y-%m-%d')

     and mt.created_by = #{createdBy}
     and mt.deleted_at = #{deletedAt}
     and mt.deleted_by = #{deletedBy}
     and mt.remark = #{remark}
     and mt.deleted = #{deleted}
     and mt.business_desc = #{businessDesc}
     and mt.mid = #{mid}
     and mt.request_crypto_transaction_endpoint = #{requestCryptoTransactionEndpoint}
     and mt.merchant_hash_secret_key = #{merchantHashSecretKey}
     and mt.notify_order_status_endpoint = #{notifyOrderStatusEndpoint}
     and mt.is_sift_on = #{isSiftOn}
     and mt.is_3ds_on = #{is3dsOn}
     and mt.crypto_delivery_method = #{cryptoDeliveryMethod}
     and mt.is_house_merchant = #{isHouseMerchant}
     and mt.notify_order_status_endpoint_2 = #{notifyOrderStatusEndpoint2}
     and mt.reserve_percentage = #{reservePercentage}
     and mt.reserve_holding_period = #{reserveHoldingPeriod}
     and mt.settlement_currency = #{settlementCurrency}
     and mt.profit_sharing = #{profitSharing}
     and mt.descriptor like concat('%', #{descriptor}, '%')
     and mt.is_whitelist_on = #{isWhitelistOn}
     and mt.notify_order_status_endpoint_3 = #{notifyOrderStatusEndpoint3}
     and mt.ani_check = #{aniCheck}
     and mt.acquirer_id = #{acquirerId}
     and mt.crypto_delivery_delay_time = #{cryptoDeliveryDelayTime}
     and mt.order_status_change_notification = #{orderStatusChangeNotification}
     and mt.three_d_success_url = #{threeDSuccessUrl}
     and mt.three_d_failure_url = #{threeDFailureUrl}
     and mt.default_redirect_success_url = #{defaultRedirectSuccessUrl}
     and mt.default_redirect_failure_url = #{defaultRedirectFailureUrl}
     and mt.on_ramp_min = #{onRampMin}
     and mt.on_ramp_max = #{onRampMax}
     and mt.off_ramp_min = #{offRampMin}
     and mt.off_ramp_max = #{offRampMax}
     and mt.merchant_fee_model_id = #{merchantFeeModelId}
     and mt.entity_id = #{entityId}
     and mt.endpoint_2_percent = #{endpoint2Percent}
     and mt.parent_id = #{parentId}
     and mt.parent_id is null
     and mt.parent_id is not null

        and date_format(convert_tz(mt.created_at,'+00:00','+08:00'),'%y%m%d') >= date_format(#{beginTime},'%y%m%d')


        and date_format(convert_tz(mt.created_at,'+00:00','+08:00'),'%y%m%d') <= date_format(#{endTime},'%y%m%d')


order by mt.id desc

